  'polNote.member': {
    en: `Taxed like any salary, Medicare levy included, plus 15.4% paid into a retirement fund (super). Money for office and travel costs is not counted. The face sits at the employee salary that would leave the same take-home pay.`,
    nl: `Belast zoals elk loon, Medicare levy inbegrepen, plus 15,4% in een pensioenfonds (super). Geld voor kantoor- en reiskosten telt niet mee. Het hoofdje staat bij het werknemersloon dat hetzelfde netto zou overlaten.`,
    fr: `Imposé comme tout salaire, Medicare levy compris, plus 15,4% versés sur un fonds de retraite (super). L'argent pour les frais de bureau et de déplacement n'est pas compté. La tête est placée au salaire d'un salarié qui laisserait le même net.`,
  },
  polNote: {
    en: links => `Hover a name for details, click to zoom in on it. Pay is yearly gross, shown on the chart as the yearly amount divided by the months paid. Each politician sits where an employee would take home the same net pay. Their pay is set by the Remuneration Tribunal: ${links}. The pay of the Reserve Bank governor and of the bosses of state-owned companies could not be confirmed, so they are left out.`,
    nl: links => `Beweeg over een naam voor details, klik om in te zoomen. Het loon is jaarlijks bruto, op de grafiek getoond als jaarbedrag gedeeld door het aantal betaalde maanden. Elke politicus staat waar een werknemer hetzelfde netto zou overhouden. Hun loon legt het Remuneration Tribunal vast: ${links}. Het loon van de gouverneur van de Reserve Bank en van de bazen van staatsbedrijven kon niet bevestigd worden en ontbreekt dus.`,
    fr: links => `Survolez un nom pour les détails, cliquez pour zoomer. La paie est un brut annuel, placé sur le graphique en montant annuel divisé par les mois payés. Chaque politicien est placé là où un salarié toucherait le même net. Leur paie est fixée par le Remuneration Tribunal : ${links}. La paie du gouverneur de la Reserve Bank et des patrons d'entreprises publiques n'a pas pu être confirmée : ils ne sont pas montrés.`,
  },
  'src.pol.mp': { en: `Remuneration Tribunal determination (compilation July 2026)`, nl: `Beslissing van het Remuneration Tribunal (consolidatie juli 2026)`, fr: `Décision du Remuneration Tribunal (compilation juillet 2026)` },
  'src.pol.office': { en: `Wikipedia: parliamentarians' salaries (Remuneration Tribunal, July 2025)`, nl: `Wikipedia: lonen van parlementsleden (Remuneration Tribunal, juli 2025)`, fr: `Wikipédia : salaires des parlementaires (Remuneration Tribunal, juillet 2025)` },

  bracketTop: { en: `45% rate`, nl: `tarief van 45%`, fr: `taux de 45%` },
  chartTitle: { en: `Tax and buying power at each salary level`, nl: `Belasting en koopkracht per loonniveau`, fr: `Prélèvements et pouvoir d'achat à chaque niveau de salaire` },
  chartAria: { en: `Tax rate per salary chart`, nl: `Grafiek van het belastingtarief per loon`, fr: `Graphique du taux de prélèvement par salaire` },
  trapTitle: { en: (a, b) => `Why the climb between ${a} and ${b}?`, nl: (a, b) => `Waarom de stijging tussen ${a} en ${b}?`, fr: (a, b) => `Pourquoi cette montée entre ${a} et ${b} ?` },
  trapBody: {
    en: (a, b, ml, mlEnd, lf, le) => `Up to ${a} you pay no income tax: the first AU$18,200 is tax-free, and AU$1,000 more is a flat allowance for work costs. Above ${ml} of taxable income, the 2% Medicare levy kicks in gently: 10 cents on each dollar above that line, until it has caught up to 2% of all your income at ${mlEnd}. In that zone each extra dollar costs 25 cents (15% tax plus 10% levy). Then the tax discount for low earners shrinks: by 5 cents per extra dollar from ${lf}, then 1.5 cents from AU$45,000 until it is gone at ${le}.`,
    nl: (a, b, ml, mlEnd, lf, le) => `Tot ${a} betaal je geen inkomstenbelasting: de eerste AU$ 18.200 zijn belastingvrij en AU$ 1.000 extra is een vaste aftrek voor werkkosten. Boven ${ml} belastbaar inkomen begint de Medicare levy van 2% zachtjes: 10 cent op elke dollar boven die grens, tot hij 2% van je hele inkomen heeft ingehaald bij ${mlEnd}. In die zone kost elke extra dollar 25 cent (15% belasting plus 10% levy). Daarna krimpt de belastingkorting voor lage inkomens: met 5 cent per extra dollar vanaf ${lf}, dan 1,5 cent vanaf AU$ 45.000 tot hij weg is bij ${le}.`,
    fr: (a, b, ml, mlEnd, lf, le) => `Jusqu'à ${a}, vous ne payez pas d'impôt sur le revenu : les premiers 18 200 AU$ sont exonérés, et 1 000 AU$ de plus sont un abattement fixe pour frais de travail. Au-delà de ${ml} de revenu imposable, le Medicare levy de 2% démarre en douceur : 10 cents sur chaque dollar au-dessus de ce seuil, jusqu'à rattraper 2% de tout votre revenu à ${mlEnd}. Dans cette zone, chaque dollar en plus coûte 25 cents (15% d'impôt plus 10% de levy). Ensuite, la réduction d'impôt pour bas revenus fond : de 5 cents par dollar en plus dès ${lf}, puis de 1,5 cent dès 45 000 AU$, jusqu'à disparaître à ${le}.`,
  },
  topTitle: {
    en: (top, mls, div) => `Why the step at ${top}${mls ? ` and the jump at ${mls}` : ''}?`,
    nl: (top, mls, div) => `Waarom de trede bij ${top}${mls ? ` en de sprong bij ${mls}` : ''}?`,
    fr: (top, mls, div) => `Pourquoi la marche à ${top}${mls ? ` et le saut à ${mls}` : ''} ?`,
  },
  topBody: {
    en: (top, mls, div) => `From ${top} your taxable income is above AU$190,000, so each extra dollar is taxed at 45%, plus the 2% Medicare levy.${mls ? ` At ${mls}, if you have no private hospital insurance, a 1% surcharge suddenly applies to all of your income, not just the part above the line (the line is AU$105,000 for a single person in 2026-27). Higher up it becomes 1.25%, then 1.5%.` : ''}${div ? ` From ${div}, your income plus retirement savings (super) pass AU$250,000, and your fund pays an extra 15% tax (called Division 293) on the super above that line.` : ''}`,
    nl: (top, mls, div) => `Vanaf ${top} ligt je belastbaar inkomen boven AU$ 190.000, dus elke extra dollar wordt belast aan 45%, plus 2% Medicare levy.${mls ? ` Bij ${mls} geldt, als je geen private hospitaalverzekering hebt, plots een toeslag van 1% op je hele inkomen, niet alleen op het deel boven de grens (de grens is AU$ 105.000 voor een alleenstaande in 2026-27). Hoger wordt dat 1,25% en dan 1,5%.` : ''}${div ? ` Vanaf ${div} komen je inkomen plus pensioensparen (super) boven AU$ 250.000, en betaalt je fonds 15% extra belasting (Division 293 genoemd) op de super boven die grens.` : ''}`,
    fr: (top, mls, div) => `À partir de ${top}, votre revenu imposable dépasse 190 000 AU$ : chaque dollar en plus est imposé à 45%, plus 2% de Medicare levy.${mls ? ` À ${mls}, sans assurance hospitalière privée, une surtaxe de 1% s'applique d'un coup à tout votre revenu, pas seulement à la part au-dessus du seuil (le seuil est de 105 000 AU$ pour une personne seule en 2026-27). Plus haut, elle passe à 1,25% puis 1,5%.` : ''}${div ? ` À partir de ${div}, votre revenu plus votre épargne retraite (super) dépassent 250 000 AU$, et votre fonds paie 15% d'impôt en plus (appelé Division 293) sur la super au-delà de ce seuil.` : ''}`,
  },

